BEGIN;
SET LOCAL ROLE s2a_management;
DO $$
DECLARE job jsonb; first_lease uuid; second_lease uuid; ident text:='imgbatch_'||replace(gen_random_uuid()::text,'-','');
BEGIN
    IF has_table_privilege('service_role','s2a_private.batch_image_runtime','SELECT') OR has_function_privilege('anon','public.s2a_batch_image_runtime_claim()','EXECUTE') THEN RAISE EXCEPTION 'batch runtime ACL mismatch'; END IF;
    INSERT INTO public.batch_image_jobs(batch_id,user_id,api_key_id,account_id,provider,model,item_count) VALUES(ident,1,1,1,'gemini_api','gemini-image',1);
    INSERT INTO s2a_private.batch_image_runtime(batch_id,user_id,key_id,group_id,account_id,key_hash,request_hash) VALUES(ident,1,1,1,1,'fixture',repeat('1',64));
    job:=public.s2a_batch_image_runtime_claim()->0;first_lease:=(job->>'lease_id')::uuid;
    IF job->>'batch_id' IS DISTINCT FROM ident OR job->>'recover_create'<>'false' THEN RAISE EXCEPTION 'claim mismatch'; END IF;
    IF public.s2a_batch_image_runtime_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'double claim'; END IF;
    IF public.s2a_batch_image_runtime_checkpoint(ident,gen_random_uuid(),'files/input','files/output')->>'error' IS DISTINCT FROM 'batch_image_lease_lost' THEN RAISE EXCEPTION 'foreign lease accepted'; END IF;
    IF public.s2a_batch_image_runtime_dispatch(ident,first_lease)->>'error' IS DISTINCT FROM 'batch_image_create_already_dispatched' THEN RAISE EXCEPTION 'create before upload'; END IF;
    IF public.s2a_batch_image_runtime_checkpoint(ident,first_lease,'files/input','files/output')->>'applied'<>'true' THEN RAISE EXCEPTION 'checkpoint failed'; END IF;
    IF public.s2a_batch_image_runtime_checkpoint(ident,first_lease,'files/input','files/output')->>'applied'<>'false' THEN RAISE EXCEPTION 'checkpoint replay'; END IF;
    IF public.s2a_batch_image_runtime_dispatch(ident,first_lease)->>'dispatched'<>'true' THEN RAISE EXCEPTION 'dispatch failed'; END IF;
    IF public.s2a_batch_image_runtime_dispatch(ident,first_lease)->>'error' IS DISTINCT FROM 'batch_image_create_already_dispatched' THEN RAISE EXCEPTION 'duplicate create'; END IF;
    UPDATE s2a_private.batch_image_runtime SET lease_until=clock_timestamp()-interval '1 second' WHERE batch_id=ident;
    job:=public.s2a_batch_image_runtime_claim()->0;second_lease:=(job->>'lease_id')::uuid;
    IF first_lease=second_lease OR job->>'recover_create'<>'true' THEN RAISE EXCEPTION 'uncertain creation not recovered'; END IF;
    IF public.s2a_batch_image_runtime_created(ident,first_lease,'batches/one')->>'error' IS DISTINCT FROM 'batch_image_lease_lost' THEN RAISE EXCEPTION 'stale writer'; END IF;
    IF public.s2a_batch_image_runtime_dispatch(ident,second_lease)->>'error' IS DISTINCT FROM 'batch_image_create_already_dispatched' THEN RAISE EXCEPTION 'recovery repeated create'; END IF;
    IF public.s2a_batch_image_runtime_created(ident,second_lease,'batches/one')->>'applied'<>'true' THEN RAISE EXCEPTION 'recovery failed'; END IF;
    IF public.s2a_batch_image_runtime_created(ident,second_lease,'batches/one')->>'applied'<>'false' THEN RAISE EXCEPTION 'created replay'; END IF;
    IF public.s2a_batch_image_runtime_created(ident,second_lease,'batches/two')->>'error' IS DISTINCT FROM 'batch_image_stage_conflict' THEN RAISE EXCEPTION 'job overwritten'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.batch_image_jobs WHERE batch_id=ident AND provider_job_name='batches/one' AND status='submitted') THEN RAISE EXCEPTION 'native job not updated'; END IF;
    IF public.s2a_batch_image_runtime_observed(ident,second_lease,'succeeded')->>'error' IS DISTINCT FROM 'batch_image_result_missing' THEN RAISE EXCEPTION 'success without result'; END IF;
    IF public.s2a_batch_image_runtime_observed(ident,second_lease,'running',NULL,'private message')->>'error' IS DISTINCT FROM 'invalid_batch_image_observation' THEN RAISE EXCEPTION 'provider message persisted'; END IF;
    IF public.s2a_batch_image_runtime_observed(ident,second_lease,'running')->>'stage' IS DISTINCT FROM 'poll' THEN RAISE EXCEPTION 'poll failed'; END IF;
    IF public.s2a_batch_image_runtime_observed(ident,second_lease,'failed')->>'error' IS DISTINCT FROM 'batch_image_lease_lost' THEN RAISE EXCEPTION 'released poll lease accepted'; END IF;
    IF public.s2a_batch_image_runtime_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'poll ignored backoff'; END IF;
    UPDATE s2a_private.batch_image_runtime SET due_at=clock_timestamp()-interval '1 second' WHERE batch_id=ident;
    job:=public.s2a_batch_image_runtime_claim()->0;first_lease:=(job->>'lease_id')::uuid;
    IF public.s2a_batch_image_runtime_observed(ident,first_lease,'succeeded','files/result')->>'stage' IS DISTINCT FROM 'index' THEN RAISE EXCEPTION 'result not queued for indexing'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.batch_image_jobs WHERE batch_id=ident AND status='indexing' AND finished_at IS NULL) THEN RAISE EXCEPTION 'unindexed result marked finished'; END IF;
    job:=public.s2a_batch_image_runtime_claim()->0;second_lease:=(job->>'lease_id')::uuid;
    IF public.s2a_batch_image_runtime_fail(ident,second_lease,'private message')->>'error' IS DISTINCT FROM 'invalid_batch_image_error' THEN RAISE EXCEPTION 'unbounded failure accepted'; END IF;
    IF public.s2a_batch_image_runtime_fail(ident,second_lease,'BATCH_RESULT_INVALID')->>'applied' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'failure transition failed'; END IF;
    IF public.s2a_batch_image_runtime_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'terminal task reclaimed'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.batch_image_jobs WHERE batch_id=ident AND status='failed' AND last_error_code='BATCH_RESULT_INVALID' AND last_error_message IS NULL AND finished_at IS NOT NULL) THEN RAISE EXCEPTION 'native terminal status mismatch'; END IF;

END $$;
ROLLBACK;
BEGIN;
SET LOCAL ROLE s2a_management;
DO $$
DECLARE u bigint;g bigint;k bigint;a bigint;unsupported bigint;h text;other_hash text;r jsonb; leased jsonb; ident text:='imgbatch_'||replace(gen_random_uuid()::text,'-','');
BEGIN
 INSERT INTO public.users(email,password_hash,balance,restrict_public_groups) VALUES('batch-'||gen_random_uuid()||'@example.invalid','!fixture',0,false) RETURNING id INTO u;
 INSERT INTO public.groups(name,platform,allow_batch_image_generation) VALUES('Batch fixture','gemini',false) RETURNING id INTO g;
 INSERT INTO public.api_keys(user_id,key,name,group_id) VALUES(u,'batch-key-'||gen_random_uuid(),'Batch fixture',g) RETURNING id,s2a_key_hash INTO k,h;
 IF public.s2a_batch_image_prepare(h,ident,repeat('a',64),'gemini-image','gemini_api',1,'images')->>'error' IS DISTINCT FROM 'batch_image_generation_forbidden' THEN RAISE EXCEPTION 'group permission bypassed'; END IF;
 UPDATE public.groups SET allow_batch_image_generation=true WHERE id=g;
 IF public.s2a_batch_image_prepare(h,ident,repeat('a',64),'gemini-image','gemini_api',1,'images')->>'error' IS DISTINCT FROM 'no_available_batch_account' THEN RAISE EXCEPTION 'empty group admitted'; END IF;
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency) VALUES('Batch account','gemini','apikey','{"api_key":"fixture-batch"}',4) RETURNING id INTO a;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(a,g);
 INSERT INTO public.accounts(name,platform,type,credentials,concurrency,priority) VALUES('Unsupported batch account','gemini','apikey','{"api_key":"fixture-other","model_mapping":{"other-*":"target"}}',4,-100) RETURNING id INTO unsupported;
 INSERT INTO public.account_groups(account_id,group_id) VALUES(unsupported,g);
 IF NOT s2a_private.batch_model_supported('{"gemini-*":"target"}','gemini-image') OR s2a_private.batch_model_supported('{"Gemini-*":"target"}','gemini-image') OR s2a_private.batch_model_supported('{"gemini-?":"target"}','gemini-x') THEN RAISE EXCEPTION 'model wildcard semantics mismatch'; END IF;
 r:=public.s2a_batch_image_prepare(h,ident,repeat('a',64),'gemini-image','gemini_api',1,'images');
 IF r->>'id' IS DISTINCT FROM ident OR r->>'ready' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'prepare failed: %',r; END IF;
 IF NOT EXISTS(SELECT 1 FROM s2a_private.batch_image_runtime WHERE batch_id=ident AND user_id=u AND key_id=k AND group_id=g AND account_id=a AND NOT ready) THEN RAISE EXCEPTION 'frozen binding mismatch'; END IF;
 IF public.s2a_batch_image_runtime_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'unpersisted request claimed'; END IF;
 IF public.s2a_batch_image_prepare(h,ident,repeat('a',64),'gemini-image','gemini_api',1,'images') IS DISTINCT FROM r THEN RAISE EXCEPTION 'prepare replay'; END IF;
 IF public.s2a_batch_image_prepare(h,ident,repeat('b',64),'gemini-image','gemini_api',1,'images')->>'error' IS DISTINCT FROM 'batch_image_conflict' THEN RAISE EXCEPTION 'request overwritten'; END IF;
 r:=public.s2a_batch_image_read(h,ident);
 IF r->>'id' IS DISTINCT FROM ident OR r ? 'key_hash' OR r ? 'account_id' OR r ? 'request_hash' OR r ? 'lease_id' THEN RAISE EXCEPTION 'unsafe batch view'; END IF;
 UPDATE public.groups SET allow_batch_image_generation=false WHERE id=g;
 IF public.s2a_batch_image_read(h,ident)->>'id' IS DISTINCT FROM ident THEN RAISE EXCEPTION 'prior batch hidden after permission disabled'; END IF;
 UPDATE public.groups SET allow_batch_image_generation=true WHERE id=g;
 INSERT INTO public.api_keys(user_id,key,name,group_id) VALUES(u,'batch-other-'||gen_random_uuid(),'Other batch key',g) RETURNING s2a_key_hash INTO other_hash;
 IF public.s2a_batch_image_read(other_hash,ident)->>'error' IS DISTINCT FROM 'batch_image_forbidden' THEN RAISE EXCEPTION 'cross-key read'; END IF;
 IF public.s2a_batch_image_list(other_hash)->>'total' IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'cross-key list'; END IF;
 IF public.s2a_batch_image_list(h)->>'total' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'own batch missing from list'; END IF;
 IF public.s2a_batch_image_content_resolve(h,ident,'cover')->>'error' IS DISTINCT FROM 'batch_image_not_completed' THEN RAISE EXCEPTION 'pending output readable'; END IF;
 IF public.s2a_batch_image_content_resolve(other_hash,ident,'cover')->>'error' IS DISTINCT FROM 'batch_image_forbidden' THEN RAISE EXCEPTION 'cross-key content'; END IF;
 IF public.s2a_batch_image_ready(h,ident,repeat('b',64))->>'error' IS DISTINCT FROM 'batch_image_conflict' THEN RAISE EXCEPTION 'ready changed hash'; END IF;
 IF public.s2a_batch_image_ready(h,ident,repeat('a',64))->>'error' IS DISTINCT FROM 'invalid_batch_pending_items' THEN RAISE EXCEPTION 'missing pending items accepted'; END IF;
 IF public.s2a_batch_image_ready(h,ident,repeat('a',64),p_items=>'[{"custom_id":"cover","prompt_preview":7}]'::jsonb)->>'error' IS DISTINCT FROM 'invalid_batch_pending_items' THEN RAISE EXCEPTION 'invalid preview accepted'; END IF;
 IF public.s2a_batch_image_runtime_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'invalid pending request became claimable'; END IF;
 IF public.s2a_batch_image_ready(h,ident,repeat('a',64),p_items=>'[{"custom_id":"cover","prompt_preview":"blue square"}]'::jsonb)->>'ready' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'ready failed'; END IF;
 IF public.s2a_batch_image_read(h,ident)->'items'->0->>'prompt_preview' IS DISTINCT FROM 'blue square' THEN RAISE EXCEPTION 'pending preview missing'; END IF;
 leased:=public.s2a_batch_image_runtime_claim()->0;
 IF leased->>'batch_id' IS DISTINCT FROM ident THEN RAISE EXCEPTION 'persisted request not claimable'; END IF;
 r:=public.s2a_batch_image_runtime_admit(ident,(leased->>'lease_id')::uuid);
 IF r->'account'->>'id' IS DISTINCT FROM a::text OR r->'account'->'credentials'->>'api_key' IS DISTINCT FROM 'fixture-batch' THEN RAISE EXCEPTION 'worker credentials not bound: %',r->>'error'; END IF;
 UPDATE public.groups SET allow_batch_image_generation=false WHERE id=g;
 IF public.s2a_batch_image_runtime_admit(ident,(leased->>'lease_id')::uuid)->>'error' IS DISTINCT FROM 'batch_image_identity_changed' THEN RAISE EXCEPTION 'worker ignored permission revocation'; END IF;
 UPDATE public.groups SET allow_batch_image_generation=true WHERE id=g;
 UPDATE public.groups SET require_oauth_only=true WHERE id=g;
 IF public.s2a_batch_image_runtime_admit(ident,(leased->>'lease_id')::uuid)->>'error' IS DISTINCT FROM 'batch_image_account_changed' THEN RAISE EXCEPTION 'worker ignored OAuth-only policy'; END IF;
 UPDATE public.groups SET require_oauth_only=false WHERE id=g;
 UPDATE public.accounts SET credentials='{"api_key":"rotated"}' WHERE id=a;
 IF public.s2a_batch_image_runtime_admit(ident,(leased->>'lease_id')::uuid)->>'error' IS DISTINCT FROM 'batch_image_account_changed' THEN RAISE EXCEPTION 'worker followed rotated credential'; END IF;
 UPDATE public.groups SET model_allowlist='{"enabled":true,"models":["allowed-*"]}' WHERE id=g;
 IF public.s2a_batch_image_prepare(h,ident,repeat('a',64),'gemini-image','gemini_api',1,'images')->>'error' IS DISTINCT FROM 'model_not_allowed' THEN RAISE EXCEPTION 'allowlist bypass'; END IF;
 UPDATE s2a_private.batch_image_runtime SET stage='index',input_ref='files/input',provider_job_name='batches/result' WHERE batch_id=ident;
 IF public.s2a_batch_image_runtime_indexed(ident,(leased->>'lease_id')::uuid,jsonb_build_array(jsonb_build_object('custom_id','cover','status','failed','image_count',0,'error_code','EMPTY_IMAGE_OUTPUT','usage',jsonb_build_object('input_tokens',-1))))->>'error' IS DISTINCT FROM 'invalid_batch_image_usage' THEN RAISE EXCEPTION 'negative batch usage accepted'; END IF;
 r:=public.s2a_batch_image_runtime_indexed(ident,(leased->>'lease_id')::uuid,jsonb_build_array(jsonb_build_object('custom_id','cover','status','failed','image_count',0,'error_code','EMPTY_IMAGE_OUTPUT','usage',jsonb_build_object('input_tokens',12,'output_tokens',0))));
 IF r->>'applied' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'batch usage completion failed: %',r; END IF;
 IF public.s2a_batch_image_read(h,ident)->'items'->0->>'prompt_preview' IS DISTINCT FROM 'blue square' THEN RAISE EXCEPTION 'preview lost during indexing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.usage_logs WHERE s2a_personal_details->>'batch_id'=ident AND user_id=u AND api_key_id=k AND account_id=a AND input_tokens=12 AND output_tokens=0 AND actual_cost=0 AND NOT (s2a_personal_details->'usage' ? 'cache_read_tokens')) THEN RAISE EXCEPTION 'batch usage identity or unknown values lost'; END IF;
 PERFORM public.s2a_batch_image_runtime_indexed(ident,(leased->>'lease_id')::uuid,'[]'::jsonb);
 IF (SELECT count(*) FROM public.usage_logs WHERE s2a_personal_details->>'batch_id'=ident)<>1 THEN RAISE EXCEPTION 'batch usage duplicated'; END IF;
 UPDATE public.batch_image_jobs SET status='completed' WHERE batch_id=ident;
 IF public.s2a_batch_image_mark_downloaded(other_hash,ident)->>'error' IS DISTINCT FROM 'batch_image_forbidden' THEN RAISE EXCEPTION 'cross-key download marking'; END IF;
 IF public.s2a_batch_image_mark_downloaded(h,ident)->>'applied' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'download marking failed'; END IF;
 IF public.s2a_batch_image_read(h,ident)->>'downloaded_at' IS NULL THEN RAISE EXCEPTION 'download timestamp hidden'; END IF;
 IF public.s2a_batch_image_list(h,20,0,NULL,'{"downloaded":true}'::jsonb)->>'total' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'downloaded filter mismatch'; END IF;
 IF public.s2a_batch_image_list(h,20,0,NULL,'{"downloaded":false}'::jsonb)->>'total' IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'undownloaded filter mismatch'; END IF;
 UPDATE public.groups SET model_allowlist='{"enabled":false,"models":[]}' WHERE id=g;
 r:=public.s2a_batch_image_prepare(h,'imgbatch_'||repeat('b',32),repeat('b',64),'gemini-image','gemini_api',1,'retry',p_parent=>ident);
 IF r ? 'error' THEN RAISE EXCEPTION 'child prepare failed: %',r; END IF;
 IF public.s2a_batch_image_read(h,'imgbatch_'||repeat('b',32))->>'parent_batch_id' IS DISTINCT FROM ident THEN RAISE EXCEPTION 'parent binding lost'; END IF;
 r:=public.s2a_batch_image_prepare(h,'imgbatch_'||repeat('d',32),repeat('d',64),'gemini-image','gemini_api',1,'nested retry',p_parent=>'imgbatch_'||repeat('b',32));
 IF r ? 'error' OR public.s2a_batch_image_read(h,'imgbatch_'||repeat('d',32))->>'parent_batch_id' IS DISTINCT FROM ident THEN RAISE EXCEPTION 'nested retry not grouped under original parent'; END IF;
 IF public.s2a_batch_image_prepare(other_hash,'imgbatch_'||repeat('c',32),repeat('c',64),'gemini-image','gemini_api',1,'retry',p_parent=>ident)->>'error' IS DISTINCT FROM 'batch_image_forbidden' THEN RAISE EXCEPTION 'cross-key parent accepted'; END IF;


END $$;
ROLLBACK;
BEGIN;
SET LOCAL ROLE s2a_management;
DO $$
DECLARE ident text:='imgbatch_'||replace(gen_random_uuid()::text,'-','');lease uuid:=gen_random_uuid();items jsonb;r jsonb;
BEGIN
 INSERT INTO public.batch_image_jobs(batch_id,user_id,provider,model,item_count,status) VALUES(ident,1,'gemini_api','gemini-image',2,'indexing');
 INSERT INTO s2a_private.batch_image_runtime(batch_id,user_id,key_id,group_id,account_id,key_hash,request_hash,stage,input_ref,provider_job_name,lease_id,lease_until)
 VALUES(ident,1,1,1,1,'fixture',repeat('a',64),'index','files/input','batches/result',lease,clock_timestamp()+interval '3 minutes');
 INSERT INTO public.batch_image_items(job_id,custom_id,status,image_count) VALUES(ident,'cover','pending',0),(ident,'missing','pending',0);
 items:=jsonb_build_array(jsonb_build_object('custom_id','cover','status','success','image_count',1,'provider_source_object','batches/'||ident||'/item-1.json','mime_type','image/png','file_extension','png'),jsonb_build_object('custom_id','missing','status','failed','image_count',0,'error_code','PROVIDER_RESULT_MISSING'));
 IF public.s2a_batch_image_runtime_indexed(ident,gen_random_uuid(),items)->>'error' IS DISTINCT FROM 'batch_image_lease_lost' THEN RAISE EXCEPTION 'index stale lease'; END IF;
 IF public.s2a_batch_image_runtime_indexed(ident,lease,jsonb_build_array(items->0))->>'error' IS DISTINCT FROM 'invalid_batch_image_index' THEN RAISE EXCEPTION 'incomplete index accepted'; END IF;
 IF public.s2a_batch_image_runtime_indexed(ident,lease,jsonb_build_array(items->0,items->0))->>'error' IS DISTINCT FROM 'invalid_batch_image_index' THEN RAISE EXCEPTION 'duplicate index accepted'; END IF;
 IF public.s2a_batch_image_runtime_indexed(ident,lease,jsonb_set(items,'{1,custom_id}','"foreign-item"'::jsonb))->>'error' IS DISTINCT FROM 'invalid_batch_image_index' THEN RAISE EXCEPTION 'unsubmitted item accepted'; END IF;
 IF EXISTS(SELECT 1 FROM public.batch_image_items WHERE job_id=ident AND status<>'pending') THEN RAISE EXCEPTION 'rejected index modified pending items'; END IF;
 IF public.s2a_batch_image_runtime_indexed(ident,lease,items)->>'applied' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'index completion failed'; END IF;
 IF (SELECT count(*) FROM public.batch_image_items WHERE job_id=ident)<>2 THEN RAISE EXCEPTION 'item count mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.batch_image_jobs WHERE batch_id=ident AND status='completed' AND success_count=1 AND fail_count=1 AND actual_cost=0 AND output_expires_at IS NOT NULL) THEN RAISE EXCEPTION 'native index totals mismatch'; END IF;
 UPDATE s2a_private.batch_image_runtime SET cleanup_requested=true WHERE batch_id=ident;
 r:=public.s2a_batch_image_cleanup_claim()->0;
 IF r->>'batch_id' IS DISTINCT FROM ident THEN RAISE EXCEPTION 'cleanup claim failed'; END IF;
 IF public.s2a_batch_image_cleanup_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'cleanup double claim'; END IF;
 IF public.s2a_batch_image_cleanup_finish(ident,gen_random_uuid())->>'error' IS DISTINCT FROM 'batch_image_cleanup_lease_lost' THEN RAISE EXCEPTION 'stale cleaner accepted'; END IF;
 IF public.s2a_batch_image_cleanup_finish(ident,(r->>'cleanup_lease')::uuid)->>'applied' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'cleanup finish failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.batch_image_jobs WHERE batch_id=ident AND status='output_deleted' AND input_deleted_at IS NOT NULL AND output_deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'cleanup native state mismatch'; END IF;
 IF public.s2a_batch_image_cleanup_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'cleaned job reclaimed'; END IF;

